# Dropzone Dropzone Компонент для загрузки файлов, без отображения индикации загрузки.
Компонент не предполагает наличия валидации, так как является частью Upload.
Но валидацию можно задать с помощью callback  `validator` . ## Быстрый старт Быстрый старт ```tsx
import React from 'react';
import { Dropzone } from '@salutejs/sdds-finai';

export function App() {
    return (
        <Dropzone
            iconPlacement="top"
            width={400}
            height={280}
            title="Click to upload"
            description="or drag and drop files here"
            onDrop={({ acceptedFiles }) => console.log('onDrop', acceptedFiles)}
            onChoseFiles={({ acceptedFiles }) => console.log('onChoseFiles', acceptedFiles)}
        />
    );
}
```

## Растягивание Растягивание С помощью свойства  `stretch`  компонент растягивается на всю доступную ширину: ```tsx
import React from 'react';
import { Dropzone } from '@salutejs/sdds-finai';

export function App() {
    return (
        <Dropzone
            stretch
            height={200}
            iconPlacement="top"
            title="Click to upload"
            description="or drag and drop files here"
        />
    );
}
```

## Множественный выбор Множественный выбор С помощью свойства  `multiple`  можно разрешить выбор нескольких файлов одновременно: ```tsx
import React from 'react';
import { Dropzone } from '@salutejs/sdds-finai';

export function App() {
    return (
        <Dropzone
            multiple
            iconPlacement="top"
            width={400}
            height={280}
            title="Click to upload"
            description="or drag and drop files here"
            onChoseFiles={({ acceptedFiles }) => console.log('Выбрано файлов:', acceptedFiles.length)}
        />
    );
}
```

## Контролируемый режим Контролируемый режим Компонент поддерживает контролируемый режим через свойство  `files` . При изменении списка файлов снаружи (например, при удалении) компонент автоматически сбрасывает состояние инпута, что позволяет повторно выбрать тот же файл: ```tsx
import React, { useState } from 'react';
import { Dropzone, Chip } from '@salutejs/sdds-finai';

export function App() {
    const [files, setFiles] = useState([]);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <Dropzone
                iconPlacement="top"
                width={400}
                height={280}
                title="Click to upload"
                description="or drag and drop files here"
                files={files}
                onChoseFiles={({ acceptedFiles }) => setFiles(acceptedFiles)}
                onDrop={({ acceptedFiles }) => setFiles(acceptedFiles)}
            />
            {files.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                    {files.map((file, index) => (
                        <Chip
                            view="clear"
                            key={index}
                            text={file.name}
                            onClickClose={() => setFiles((prev) => prev.filter((_, i) => i !== index))}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}
```

## Валидация Валидация С помощью свойства  `validator`  можно задать функцию валидации файлов. Она вызывается перед  `onDrop`  и  `onChoseFiles`  и должна вернуть объект с  `acceptedFiles`  и опционально  `rejectedFiles` : ```tsx
import React, { useState } from 'react';
import { Dropzone } from '@salutejs/sdds-finai';

export function App() {
    const [log, setLog] = useState('');

    const validator = async (files) => {
        const acceptedFiles = files.filter((f) => f.size < 1024 * 1024);
        const rejectedFiles = files.filter((f) => f.size >= 1024 * 1024);
        return { acceptedFiles, rejectedFiles };
    };

    const handleChoseFiles = ({ acceptedFiles, rejectedFiles }) => {
        if (rejectedFiles.length) {
            setLog(`Отклонено файлов: ${rejectedFiles.length} (больше 1 МБ)`);
        } else {
            setLog(`Принято файлов: ${acceptedFiles.length}`);
        }
    };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <Dropzone
                iconPlacement="top"
                width={400}
                height={280}
                title="Только файлы до 1 МБ"
                description="or drag and drop files here"
                validator={validator}
                onChoseFiles={handleChoseFiles}
            />
            {log && <p>{log}</p>}
        </div>
    );
}
```
